from __future__ import annotations
import pathlib

# Source-local staging DDL. The warehouse-level normalized schema lives at
# ../../../../schema/frontier_postgres.sql. This table mirrors canonical JSONL
# without discarding rich nested structures.
def generate_bigquery_ddl() -> str:
    return """CREATE TABLE IF NOT EXISTS `clinicaltrials.studies_v3` (
 nct_id STRING NOT NULL,
 brief_title STRING NOT NULL,
 official_title STRING,
 acronym STRING,
 nct_id_aliases ARRAY<STRING>,
 org_study_id_info JSON,
 secondary_id_infos JSON,
 organization JSON,
 brief_summary STRING,
 detailed_description STRING,
 overall_status STRING,
 why_stopped STRING,
 expanded_access_info JSON,
 phase ARRAY<STRING>,
 study_type STRING,
 design JSON,
 enrollment_count INT64,
 enrollment_type STRING,
 conditions ARRAY<STRING>,
 keywords ARRAY<STRING>,
 sponsors JSON,
 start_date DATE,
 start_date_type STRING,
 primary_completion_date DATE,
 primary_completion_date_type STRING,
 completion_date DATE,
 completion_date_type STRING,
 study_first_submit_date DATE,
 study_first_post_date DATE,
 last_update_submit_date DATE,
 last_update_post_date DATE,
 last_update_post_date_type STRING,
 eligibility_criteria STRING,
 minimum_age STRING,
 maximum_age STRING,
 sex STRING,
 gender_based BOOL,
 gender_description STRING,
 healthy_volunteers BOOL,
 standard_ages ARRAY<STRING>,
 eligibility JSON,
 arms JSON,
 interventions JSON,
 central_contacts JSON,
 overall_officials JSON,
 locations JSON,
 primary_outcomes JSON,
 secondary_outcomes JSON,
 other_outcomes JSON,
 references JSON,
 see_also_links JSON,
 available_ipds JSON,
 ipd_sharing JSON,
 oversight JSON,
 has_results BOOL,
 is_fda_regulated_drug BOOL,
 is_fda_regulated_device BOOL,
 protocol_section JSON,
 results_section JSON,
 annotation_section JSON,
 document_section JSON,
 derived_section JSON,
 run_id STRING NOT NULL,
 source STRING NOT NULL,
 source_record_sha256 STRING NOT NULL,
 source_data_timestamp TIMESTAMP NOT NULL,
 source_api_version STRING NOT NULL,
 parser_version STRING NOT NULL,
 canonical_schema_version STRING NOT NULL,
 retrieved_at TIMESTAMP NOT NULL,
 source_url STRING
)
PARTITION BY last_update_post_date
CLUSTER BY overall_status, study_type, nct_id;
"""


def generate_postgres_ddl() -> str:
    return """CREATE TABLE IF NOT EXISTS clinicaltrials_studies_v3 (
 nct_id TEXT PRIMARY KEY,
 brief_title TEXT NOT NULL,
 official_title TEXT,
 acronym TEXT,
 nct_id_aliases TEXT[] NOT NULL DEFAULT '{}',
 org_study_id_info JSONB NOT NULL DEFAULT '{}'::jsonb,
 secondary_id_infos JSONB NOT NULL DEFAULT '[]'::jsonb,
 organization JSONB NOT NULL DEFAULT '{}'::jsonb,
 brief_summary TEXT,
 detailed_description TEXT,
 overall_status TEXT,
 why_stopped TEXT,
 expanded_access_info JSONB NOT NULL DEFAULT '{}'::jsonb,
 phase TEXT[] NOT NULL DEFAULT '{}',
 study_type TEXT,
 design JSONB NOT NULL DEFAULT '{}'::jsonb,
 enrollment_count INTEGER,
 enrollment_type TEXT,
 conditions TEXT[] NOT NULL DEFAULT '{}',
 keywords TEXT[] NOT NULL DEFAULT '{}',
 sponsors JSONB NOT NULL DEFAULT '{}'::jsonb,
 start_date DATE,
 start_date_type TEXT,
 primary_completion_date DATE,
 primary_completion_date_type TEXT,
 completion_date DATE,
 completion_date_type TEXT,
 study_first_submit_date DATE,
 study_first_post_date DATE,
 last_update_submit_date DATE,
 last_update_post_date DATE,
 last_update_post_date_type TEXT,
 eligibility_criteria TEXT,
 minimum_age TEXT,
 maximum_age TEXT,
 sex TEXT,
 gender_based BOOLEAN,
 gender_description TEXT,
 healthy_volunteers BOOLEAN,
 standard_ages TEXT[] NOT NULL DEFAULT '{}',
 eligibility JSONB NOT NULL DEFAULT '{}'::jsonb,
 arms JSONB NOT NULL DEFAULT '[]'::jsonb,
 interventions JSONB NOT NULL DEFAULT '[]'::jsonb,
 central_contacts JSONB NOT NULL DEFAULT '[]'::jsonb,
 overall_officials JSONB NOT NULL DEFAULT '[]'::jsonb,
 locations JSONB NOT NULL DEFAULT '[]'::jsonb,
 primary_outcomes JSONB NOT NULL DEFAULT '[]'::jsonb,
 secondary_outcomes JSONB NOT NULL DEFAULT '[]'::jsonb,
 other_outcomes JSONB NOT NULL DEFAULT '[]'::jsonb,
 references JSONB NOT NULL DEFAULT '[]'::jsonb,
 see_also_links JSONB NOT NULL DEFAULT '[]'::jsonb,
 available_ipds JSONB NOT NULL DEFAULT '[]'::jsonb,
 ipd_sharing JSONB NOT NULL DEFAULT '{}'::jsonb,
 oversight JSONB NOT NULL DEFAULT '{}'::jsonb,
 has_results BOOLEAN,
 is_fda_regulated_drug BOOLEAN,
 is_fda_regulated_device BOOLEAN,
 protocol_section JSONB NOT NULL,
 results_section JSONB NOT NULL DEFAULT '{}'::jsonb,
 annotation_section JSONB NOT NULL DEFAULT '{}'::jsonb,
 document_section JSONB NOT NULL DEFAULT '{}'::jsonb,
 derived_section JSONB NOT NULL DEFAULT '{}'::jsonb,
 run_id UUID NOT NULL,
 source TEXT NOT NULL,
 source_record_sha256 CHAR(64) NOT NULL,
 source_data_timestamp TIMESTAMPTZ NOT NULL,
 source_api_version TEXT NOT NULL,
 parser_version TEXT NOT NULL,
 canonical_schema_version TEXT NOT NULL,
 retrieved_at TIMESTAMPTZ NOT NULL,
 source_url TEXT
);
CREATE INDEX IF NOT EXISTS idx_ctg_v3_last_update_post ON clinicaltrials_studies_v3(last_update_post_date DESC);
CREATE INDEX IF NOT EXISTS idx_ctg_v3_conditions_gin ON clinicaltrials_studies_v3 USING GIN (conditions);
CREATE INDEX IF NOT EXISTS idx_ctg_v3_phase_gin ON clinicaltrials_studies_v3 USING GIN (phase);
CREATE INDEX IF NOT EXISTS idx_ctg_v3_protocol_gin ON clinicaltrials_studies_v3 USING GIN (protocol_section jsonb_path_ops);
"""


def save_ddls(output_dir: pathlib.Path) -> None:
    output_dir.mkdir(parents=True, exist_ok=True)
    (output_dir / "bigquery_studies.sql").write_text(generate_bigquery_ddl(), encoding="utf-8")
    (output_dir / "postgres_studies.sql").write_text(generate_postgres_ddl(), encoding="utf-8")
